    /**
     * The other values of an enumeration in webtrees, as suggestions for a phrase, e.g. "Foster" for PEDI.
     *
     * @return list<string>
     */
    private static function suggestions(ElementInterface $element, string $type): array
    {
        $suggestions = [];

        foreach ($element->values() as $value => $label) {
            if ($value !== '' && !in_array((string) $value, Gedcom7Schema::ENUMERATIONS[$type] ?? [], true)) {
                $suggestions[] = strip_tags($label);
            }
        }

        return $suggestions;
    }

    /**
     * The relationships of webtrees that are not roles of GEDCOM 7.0, as suggestions for a phrase, e.g. "Godmother".
     *
     * @return list<string>
     */
    private static function relationships(): array
    {
        $suggestions = [];

        foreach ((new RelationIsDescriptor(''))->values() as $value => $label) {
            if ($value !== '' && !isset(Gedcom7Converter::ROLES[strtoupper((string) $value)])) {
                $suggestions[] = strip_tags($label);
            }
        }

        return $suggestions;
    }
